import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"周易经传集解卷三十四","description":"周易经传集解 - 周易经传集解卷三十四","frontmatter":{"title":"周易经传集解卷三十四","description":"周易经传集解 - 周易经传集解卷三十四"},"headers":[],"relativePath":"zh/classics/jingchuan-jijie/035.md","filePath":"zh/classics/jingchuan-jijie/035.md"}'),r={name:"zh/classics/jingchuan-jijie/035.md"};function c(o,a,l,d,p,h){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易经传集解卷三十四",tabindex:"-1"},[n("周易经传集解卷三十四 "),e("a",{class:"header-anchor",href:"#周易经传集解卷三十四","aria-label":"Permalink to “周易经传集解卷三十四”"},"​")],-1),e("p",null,"钦定四库全书周易经传集解卷三十四 ​宋林栗撰。八卦成列，象在其中矣；因而重之，爻在其中矣；刚柔相推，变在其中矣；系辞焉而命之，动在其中矣。吉凶悔吝者，生乎动者也。刚柔者，立本者也。变通者，趋时者。吉凶者，贞胜者也。天地之道，贞观者也；日月之道，贞明者也；天下之动，贞夫一者也。夫乾，确然示人易矣。夫坤𬯎然示人简矣。爻也者，效此者也。象也者，像此者也。爻象动乎内，吉凶见乎外，功业见乎变，圣人之情见乎辞。天地之大德曰生，圣人之大宝曰位。何以守位曰仁，何以聚人曰财。理财正辞，禁民为非曰义。上章首论乾坤，次言爻象；此章首言爻象，次论乾坤。圣人反复赞明，以晓学者。乾坤见于爻象，爻象出于乾坤，求而得之，无他义也。今以八卦成列而观之，则六十四象在其中矣。因而重之，每卦六画，则三百八十四爻在其中矣。象成而未推，则先后不可见，故刚柔相推，而六十四象之变在其中矣。爻成而未系，则吉凶不可见，故系辞而命之以吉凶，则三百八十四爻之动在其中矣。吉凶悔吝生乎动，是以系之辞也。易曰：「动悔有悔，征吉。」王通乃谓「不动则无悔」，言易者从而和之。生乎天地之间，嗜欲饥渴，犹夫人也，而欲不动，得乎哉？至言「功业见乎变」，则又不得而恶夫动矣。是故刚柔相推，以立一卦之本；六爻变通，以趋一卦之时；吉凶悔吝，以辨六爻之胜。此圣人之所以为易者也，岂曰「不动」云乎哉？其曰「吉凶者，贞胜」，何谓也？刚胜则柔伏，柔胜则刚陵。卦必有本，有本斯有时；爻必有正，有正斯有胜。爻之正者，卦之本也；爻之胜者，卦之时也。其吉凶之辞，则视其所以为正者，胜与不胜而已。胜则系之以吉，不胜则系之以凶。何谓正？所以为天地之正者，万物可见是也，故曰「贞观」。所以为日月之正者，天下常明是也，故曰「贞明」。所以为天下之正者，民无二王是也，故曰「贞一」。万物不可见，则天地息矣；天下不常明，则日月废矣；民不知有君，则天下乱矣。故卦必立之本，爻必取其正，然后视其刚柔之胜，以为吉凶悔吝之辞也。是故有贞吉，有贞凶，有利贞，有勿用贞，有可贞，有不可贞，有贞厉，有贞悔亡，有贞吝，有贞无咎。而说者乃曰：「吉凶之来，唯正可以胜之。」若是则一言而足矣，又何尚于易乎？夫微子去之，箕子为之奴，比干谏而死，彼三人者，孰为正胜也哉？或曰：乾坤成列，而易列乎其中矣；八卦成列，而象在其中矣。何以异乎？曰：无以异也。八卦之为六十四，重之而可见也。乾坤之为六十四，变之而可见也。方其未重未变也，果安在乎？固以先立乎其中矣。确，刚貌也。易言：「确乎其不可拔也。」𬯎，柔貌也。礼言：𬯎乎其顺也。乾刚之粹，故其体确然，而示人以易知。坤柔之纯，故其体𬯎然，而示人以简能。惟简且易，故变于六十四卦，动于三百八十四爻，而所以为确然之刚，𬯎然之柔者，常自若也。是故爻也者，效其刚柔者也；象也者，像其刚柔者也。象有变通，辞有鼓舞，故爻象动乎内，而吉凶见乎外。祸可转而为福，败可因而为成，故功业见乎变。事有若难而易，𫝑有若危而安，故圣人之情见乎辞。天地之德大矣，语其大者，莫大于生也。生也者，变化是也，其在易则生生是也。圣人之宝大矣，语其大者，莫大于位也。位也者，尊卑是也，其在易则六位是也。天地之道，刚与柔也。圣人之道，仁与义也。以财聚人，以人守位，则谓之仁；以正理财，以理禁民，则谓之义。仁义之不可偏用，犹阴阳之不可偏胜也。圣人之用仁义也，犹天地之用阴阳也，岂可以迹而求之哉？非正不可以理财，非财不可以聚人，非理不可以禁民，非民不可以守位。故天地之化成也，不知其孰为阴，孰为阳；圣人之化成也，不知其孰为仁，孰为义。此易之道，所以与天地圣人为一者也。苏氏曰：「理财者，疏理其出入之道，使不壅也。」正辞，正名也。无道之世，唯不正其名，故上有愧于辞，而下不直其上。令之不得，诛之不止，何以禁民之为非也。斯言得之矣。古者包牺氏之王天下也，仰则观象于天，俯则观法于地，观鸟兽之文，与地之宜，近取诸身，远取诸物，于是始作八卦，以通神明之德，以类万物之情。作结绳而为网罟，以佃以渔，盖取诸离。包牺氏没，神农氏作。斲木为耜，揉木为耒，耒耨之利，以教天下，盖取诸益。日中为市，致天下之民，聚天下之货，交易而退，各得其所，盖取诸噬嗑。神农氏没，黄帝、尧、舜氏作，通其变，使民不倦，神而化之，使民宜之。易穷则变，变则通，通则久。是以「自天祐之，吉无不利」。黄帝、尧、舜垂衣裳而天下治，盖取诸乾坤。刳木为舟，剡木为楫，舟楫之利，以济不通，致远以利天下，盖取诸涣。服牛乘马，引重致远，以利天下，盖取诸随。重门击柝，以待暴客，盖取诸豫。断木为杵，掘地为臼，臼杵之利，万民以济，盖取诸小过。弦木为弧，剡木为矢，弧矢之利，以威天下，盖取诸暌。上古穴居而野处，后世圣人易之以宫室，上栋下宇，以待风雨，盖取诸大壮。古之葬者，厚衣之以薪，葬之中野，不封不树，丧期无数，后世圣人易之以棺椁，盖取诸大过。上古结绳而治，后世圣人易之以书契，百官以治，万民以察，盖取诸夬。是故易者，象也。象也者，像也；彖者，材也；爻也者，效天下之动者也。是故吉凶生而悔吝著也。前章既言象之所以像，爻之所以效，此章遂言圣人观象以备物致用，立成器以为天下利也。包牺，一曰伏羲，或言其姓氏之义，或言其年世之数，自汉以来难知矣。要之，古圣人始作八卦者也。「观象于天」，观其确然者也。「观法于地」，观其𬯎然者也。「观鸟兽之文」，龙虎鸟龟是也。「观地之宜」，山川原隰是也。在天有其象者，在地有其法；在地有其宜者，在天有其文。「近取诸身」，志气形骸是也；「远取诸物」，禽兽草木是也。在我有其理者，在物有其生。在物有其知者，在我有其义。圣人以天地人物而参诸身，于是始作八卦。是故天地有神明之异，通其德则匪殊；物我有灵昧之殊，类其情则为一。神明之德，万物之情，既已包括乎爻象之中，则备物致用，唯听所取而已。此圣人得天下之至赜，取诸物宜而不可恶者也。试递言之。「上目为罔，下目为罟」，畋渔之象也。离为目，为飞鸟，为鱼鳖。巽为绳，兑为泽。结其绳，张其目，高则飞鸟丽之，下则鱼鳖丽之。盖取诸离象，然后畋渔之象备之。「上木为耒，下木为耨」，耒耨之象也。震为动，坤为土，艮为坚木，巽为入，而又有「兑」象焉。兑为金。木用其坚，金致其锐，动而入土，土乃发生，然后耒耨之象备矣。「日丽乎上，足动乎下」，日中为市之象也。震为动，艮为止，坎为通，离为丽，动为止，易通与丽交，然后交易之象备矣。上尊为衣，下卑为裳，衣裳之象也。「乾为大赤」，非「坤」则不为玄。「坤为大黑」，非「乾」则不为𫄸。乾坤成列，而后衣裳之象备矣。木行于上，水流于下，舟楫之象也。「坎」为水，震为足，艮为手，巽为木，兑为金。金以制木，木以行水，人之手足动乎其中，然后舟楫之象备矣。足共其事，口仰于人，牛马之象也。震为动，艮为止，巽为木，兑为金。金以为衔，木以为梏，随人而作，随人而止，然后服牛乘马之象备矣。内阖其门，外鸣其柝，备豫之象也。坤为夜，为阖户。艮为径路、为门阙。坎为盗，为隐伏。震为呜，为大涂。夫盗昼伏夜动，或潜于径路，或出于大涂，或伏于门阙。主人阖其户，鸣柝而惊之，然后重门击柝之象备矣。土止于下，木动于上，臼杵之象也。艮为土，又为手，巽为木，兑为金，震为足。断木为杵，掘地为臼。木、金以为器，手、足以为用，然后杵臼之象备矣。毁折为弧，戈兵为矢，弧矢之象也。兑为金，离为火、为电、为矢，坎为弓，巽为木。以金治材，以为弧矢，以威天下，如火如电，然后弧矢之象备矣。下天为宇，上木为栋，宫室之象也。乾为天，兑为泽，震为木，巽为风，艮为阙。风行于木，泽上于天，而巍然门阙，不动乎上，然后宫室之象备矣。木周其内，金锢其外，棺椁之象也。巽为木，为入，乾为人，兑为金，为刚卤之地。木以为藏，金以为固，内外周身，以入于土，然后棺椁之象备矣。君用其刚，民从其决，书契之象也。乾为金，兑为口，巽为绳，又为本。以金削木而为契，以口谐声而为书记，文明遂以代结绳之政，然后书契之象备矣。是故观乎重离，则见上网下罟之象；「观乎益」，则见上耒下耜之象；「观乎噬嗑」，则见三阳为人，三阴为货，交易之象；「观乎乾坤」，则见六幅为衣，十二幅为裳，尊卑之象；「观乎涣」，则见人动乎上，楫动乎下，舟行之象；「观乎随」，则见服牛乘马，引重之象；「观乎豫」，则见内外重门，闭固之象；观乎小过，则见臼杵、椎舂之象；观乎暌，则见张弧挟矢之象；观乎大壮，则见宫室、门阙之象；观乎大过，则见舆棺辇椁之象；「观乎夬」，则见书契、缄縢之象。圣人岂苟云乎哉？然而独于黄帝、尧、舜言「通其变，使民不倦，神而化之，使民宜之」，何也？岂包牺、神农之时未能变通也？或曰：「不然。所谓变化者，乾坤之道也，取诸乾坤，故不得不兼言乎变化也。」又曰：「易穷则变，变则通，通则久，不于它卦而独于此，何谓也？」曰：「乾坤，易之缊也，取诸乾坤，故不得不兼言乎易也。」其在他卦，岂得而该徧之哉？故曰：易者，象也；象也者，像其形容也。彖者，材也；材也者，辨其材用也。爻也者，效也，效天下之动也。既效其动，是故吉凶生而悔吝著也。苏氏曰：「彖，彖也。爻折俎，包牺象之矣。」或曰：伏羲始画八卦，文王重易六爻。方其未重也，备物致用，于何而取之？曰：八卦成列，象在其中矣；因而重之，爻在其中矣。至于文王，实始作易，布其爻而系之辞，前乎此者，未尝无六十四也。周官三易，盖有之矣。然包牺作结绳为网罟，神农作耒耜通交易，黄帝、尧、舜垂衣裳而作舟楫，服牛乘马，重门击柝，臼杵弧矢，栋宇书契，皆在三易之前，盖得其意云尔，非必即其书而取其义，因其象而致其用也。子云：「上古结绳而治，后世圣人易之以书契，百官以治，万民以察，盖取诸夬。」然则未有书契以前，安得夬卦而取之哉？近世学者，必欲言伏羲既画八卦，又因而重之者，非矣。阳卦多阴，阴卦多阳，其故何也？阳卦奇，阴卦耦。其德行何也？阳一君而二民，君子之道也。阳二君而一民，小人之道也。易曰：「憧憧往来，朋从尔思。」子曰：「天下何思何虑？」天下同归而殊涂，一致而百虑，天下何思何虑？「日往则月来，月往则日来，日月相推而明生焉。寒往则暑来，暑往则寒来，寒暑相推而岁成焉。往者屈也，来者信也，屈信相感而利生焉。尺蠖之屈，以求信也。龙蛇之蛰，以存身也。精义入神，以致用也。利用安身，以崇德也。过此以往，未之或知也。穷神知化，德之盛也。」易曰：「困于石，据于蒺藜，入于其宫，不见其妻，凶。」子曰：「非所困而困焉，名必辱；非所据而据焉，身必危。既辱且危，死期将至，妻其可得见邪？」易曰：「公用射隼于高墉之上，获之，无不利。」子曰：「隼者，禽也；弓矢者，器也；射之者，人也。君子藏器于身，待时而动，何不利之有？动而不括，是以出而有获，语成器而动者也。」子曰：「小人不耻不仁，不畏不义，不见利不劝，不威不惩。小惩而大诫，此小人之福也。易曰：屦校灭趾，无咎。此之谓也。」「善不积，不足以成名；恶不积，不足以灭身。小人以小善为无益而弗为也，以小恶为无伤而弗去也，故恶积而不可揜，罪大而不可解。易曰：何校灭耳，凶。」子曰：「危者，安其位者也；亡者，保其存者也；乱者，有其治者也。」是故君子安而不忘危，存而不忘亡，治而不忘乱，是以身安而国家可保也。易曰：其亡其亡，系于苞桑。子曰：「德薄而位尊，知小而谋大，力小而任重，鲜不及矣。易曰：鼎折足，覆公𫗧，其形渥，凶。言不胜其任也。」子曰：「知几其神乎？君子上交不谄，下交不渎，其知几乎？几者，动之微，吉之先见者也。君子见几而作，不俟终日。易曰：介于石，不终日，贞吉。介如石焉，宁用终日，断可识矣。君子知微知彰，知柔知刚，万夫之望。」子曰：「颜氏之子，其殆庶几乎？有不善，未尝不知之者，未尝复行也。易曰：不远复，无祗悔，元吉。天地𬘡缊，万物化醇。男女搆精，万物化生。易曰：三人行，则损一人；一人行，则得其友。言致一也。」子曰：「君子安其身而后动，易其心而后语，定其交而后求。君子修此三者，故全也。危以动，则民不与也；惧以语，则民不应也；无交而求，则民不与也。莫之与，则伤之者至矣。易曰：莫益之，或击之，立心勿恒，凶。」前章既言十三卦之象，此章遂言十卦之爻，所谓天下之至动，观其会通而不可乱者也。阳以一为君而二为民，阴以二为君，而一为民。此阳卦之所以多阴，阴卦之所以多阳，民多而君少，其故然也。一君二民，君子之道；二君一民，小人之道。此阳卦之所以奇，阴卦之所以耦。奇尊而耦卑，奇贵而耦贱，其德行然也。阳出于「乾」，君之象也。阴出乎「坤」，民之象也。「震」「坎」「艮」一阳而二阴，是「乾」为君而「坤」为民也。「巽」「离」「兑」一阴而二阳，是「坤」为君而「乾」为民也。此其所以为君子小人之道欤！易曰：「憧憧往来，朋从尔思。」「咸」九四之辞也。「咸」，感也。柔上而刚下，二气感应以相与，所以为「咸」也。其在六爻，三阴三阳，各有其配。五应在二，比于上而志乎末；三应在上，比于二而执乎下。故三与五两朱其民，而二与四皆畔其君，何也？三五皆以刚居刚，而体乎「乾」，二四皆以柔居柔，而体乎「巽」。漠然无相与之意，欲其感应，难矣。惟初六以阴居刚，九四以阳居柔，而又「艮」下「兑」上，得乎相与之义。其应既专，其情且速，故其往来相求，中心憧憧然，如恐弗获也。感应之道，固如是矣。故曰「贞吉悔亡」。或曰：九五、六二，阴阳并毗，刚上柔下，固无相与之义也。九三、上六虽曰并毗，而柔上刚下，二气感应，谓之相与，不亦可乎？初六、九四虽阴阳互居，而刚上柔下，于咸之道亦有未至，然其得失臧否若是不同，何也？曰：三乾震也，而上为巽，是二君而一民也。四上下兑也，而初为民，是二民而一君也。震巽为长，艮兑为少，此其所以辨之与？思者，心也。朋者，众也。四于六爻，心之谓也。下兑上兑，朋之象也。爱人者，人恒爱之。敬人者，人恒敬之。君之视臣如手足，则臣视君如腹心。朋从尔思，不亦宜乎？然以位则未光，以时则未大，故犹有憧憧之辞也。夫子言之曰：「天下何思何虑？天下同归而殊涂，一致而百虑，天下何思何虑？」以心观心，千万人之心，一人之心是也。夫又别有何思，别有何虑哉？又曰：「往者屈也，来者信也，屈信相感而利生焉。」往者为屈，男下女也；来者为信，妇从夫也。我往则彼来，我不肯往，彼曷为来哉？有屈则有信，身不肯屈，道何自信哉？诗云：「莫往莫来，悠悠我思。」则异乎憧憧朋来之义矣。故以日月寒暑明往来之义，又以尺蠖龙蛇辨屈信之理。不往则不来，不屈则不信也。夫往来之义，日月寒暑所不免，而况于人乎？屈信之理，尺蠖龙蛇且犹知之，而况于人乎？天地之运，人物之情，莫不皆然，可谓殊涂而同归，百虑而一致矣。故又曰：「精义入神以致用也；利用安身以崇德也。」精乎屈信往来之义而入于神，非特退藏于密也，亦将以致其用也。利乎屈信往来之用而安其身，非特与民同患也，亦将以崇其德也。或曰：精义入神，何谓也？曰：穷理而至于命也。利用安身，何谓也？曰：利物者，所以自安也。龙蛇之蛰，但言存身者，身存则卒起而变化矣。故虽圣人，犹以安身为本，身安而后德可崇也。出而致用，入而崇德，亦往来屈信之理。过此以往，则外化内神之事也。孟子曰：「大而化之之谓圣，圣而不可知之之谓神。」又曰：「所过者化，所存者神。」传曰：「一则神，两则化。」由是言之，亦往来屈信之理也。夫子以其难言，而当世之人不足与有明也，故曰「未之或知也」。穷神知化，德之盛也。惟盛德者，为能穷而知之矣。或曰：咸之九四，足以充穷神知化之事乎？曰：不然。诗之𬳶曰「思无邪」，本言牧马之事，非言诗也。而夫子取其一言，言诗之大旨，曰：诗三百，一言以蔽之，曰思无邪。今咸之九四曰：憧憧往来，朋从尔思，本言上下感应之事，非言易也。而夫子取其一言，言易之大旨，自日月寒暑之章章，至于穷神知化之微妙，皆一以贯之，所谓「观其所感，而天地万物之情可见」者也。古人断章取义，多如是矣。故自此以下，错举诸卦之爻，以明著其例，或在初上，或在二三四，而各主一卦之义，独不举五爻者，志可知矣。凡此十爻，其初为君子，其五为小人，独噬嗑举其二者，初上为小人，终始故也。苟不求其故，考其德行，何从而见之哉？逐爻之义，各释于本卦。子曰：乾坤，其易之门邪？乾，阳物也。坤，阴物也。阴阳合德，而刚柔有体，以体天地之撰，以通神明之德。其称名也，杂而不越，于稽其类，其衰世之意邪？夫易彰往而察来，而微显阐幽，开而当名辨物，正言断辞，则备矣。其称名也小，其取类也大。其旨远，其辞文，其言曲而中，其事肆而隐。因二以济民行，以明失得之报。此一节为简编脱乱，失其伦次。自「通神明之德」，下文当曰：「其称名也小，其取类也大。」至「明失得之报」，下文当曰：「其称名也，杂而不越。于稽其类，其衰世之意邪？」脱一简在后，后脱二简在前。妄儒小生，记诵不精，从而次之，故缪紊若此也。「微显阐幽」下有「开」字，盖书生注于句绝，以训释「阐」字耳，非本文也。夫子既言十三卦之象、十卦之爻，此章复言其皆自乾坤而出也，故曰「乾坤其易之门」也。或曰：「易之缊，易之门」，有以异乎？曰：无以异也。言其具乎中，则谓之缊，言其所由出则谓之门。缊，盖藏也。门，阖辟也。乾为健为天，阳之物也。坤为顺为地，阴之物也。阴阳合德而后能生刚柔，有体而不可易。变化者，天地之撰也。易简者，神明之德也。天地之撰，一生一成，以此而体。神明之德，一动一静，以此而通。其称名也，曰「乾」曰「坤」，可谓小矣。其取类也，为天为地，可谓大矣。及其成书也，既往无不彰，方来无不察，至显无不微，至幽无不阐，名无不当，物无不辨，言无不正，辞无不断，则可谓备矣。彰往察来，故远而文；微显阐幽，故肆而隐。当名辨物，故杂而不越；正言断辞，故曲而中。夫易本于画，画不足，故称其名。名者，彖也，乾、坤、屯、蒙、需、讼、师、比是也。名不足，故辨诸物。物者，象也，「潜龙」、「见龙」、「履霜、坚冰」是也。物不足，故正言之。正言之者，「终日乾乾，夕惕若」之类是也。言不足，故断以辞。断以辞者，「勿用利见」，「厉无咎」之类是也。或曰：「何谓肆而隐？」曰：发挥天下之至赜，故幽者阐而肆；包罗天下之至动，故显者隐而微。刚柔动静，是之谓贰；吉凶悔吝，是之谓因。因其贰以为吉凶，所以明失得之报，以济斯民之行也。「何谓杂而不越？」曰：大畜、小畜，皆畜也；大过、小过，皆过也。屯，难也；蹇，亦难也。晋，进也；渐，亦进也。临，大也；礼，亦大也。然而临不可以为丰，渐不可以为晋，大畜不可以为小畜，小过不可以为大过，此所谓杂而不越也。于是焉而稽其类，则见圣人测隐忧患之心，故曰：其衰世之意耶？非衰世人，则其操心不能若是之危，而虑患不能若是之深矣。易之兴也，其于中古乎？作易者，其有忧患乎？是故履，德之基也；谦，德之柄也；复，德之本也；恒，德之固也；损，德之修也；益，德之裕也；困，德之辨也；井，德之地也；巽，德之制也。履，和而至；谦，尊而光；复，小而辨于物；恒，杂而不厌；损，先难而后易；益，长裕而不设；困，穷而通；井，居其所而迁；巽，称而隐。履以和行，谦以制礼，复以自知，恒以一德，损以远害，益以兴利，困以寡怨，井以辨义，巽以行权。夫子既言易有衰世之意，此章遂言九卦之大义，以见圣人忧患之心，故曰：「易之兴也，其于中古乎？」夫易作于文王，成于周公，夫子盖知之矣。然犹若疑而叹之，何也？曰：夫子当周之衰，行乎忧患之域，所遭所历，变故万端，而作易者皆已预言之，如足履而目见之者，非文王、周公，其谁系之？此夫子所以若发疑而深叹之也。九卦之义，各随其彖释之。易之为书也不可远，为道也屡迁，变动不居，周流六虚，上下无常，刚柔相易，不可为典要，唯变所适。其出入以度，外内使知惧。又明于忧患与故，无有师保，如临父母。初率其辞而揆其方，既有典常，苟非其人，道不虚行。夫子既言十三卦之象、十卦之爻、九卦之彖，盖举一隅之意耳。此三章遂明易之为书，不可远，不可执，始终条理，广大悉备，学者深求而后得之也。中庸曰：「道也者，不可须臾离也，可离非道也。」又曰：「道不远人，人之为道而远人，不可以为道。」故易之为书，切于斯人起居出入、视听言动之间，君子造次颠沛必于是也。书曰：「德无常师，主善为师。善无常主，协于克一。」故易之为书，虽不可远，然其为道也屡迁，亦不可执一以求之也。何为其然也？以其升降往来，变动不居，而周流乎六虚之位，是以屡迁而不可远也。贵不必上，贱不必下，是谓无常。刚往则柔来，柔往则刚来，是谓相易。不可定之以为典常，不可总之以为要会，唯其变化所适，则从而求之可也。外卦为出，内卦为入。凡易之内外出入者，所以为民外内出入之度，使之观其吉凶而知所戒惧也。又明示以忧患之故，使知其微渐而早图之，圣人之意可谓勤矣。「与」字当为「之」字之误。说者谓明忧患与其故，虽若无害于理，然上文使知惧，则既明忧患矣，此又中言之，何哉？师，父道也；保，母道也。师保之前，如临父母，宜也。今旡师保在前，而严惮其辞，爱戴其德，如父母实临之，何也？盖以圣人之作易，其于天下后世，不啻如其父母师保之心也。率，循也。揆，度也。方，所也。既，终也。学者之读其书，能如父母师保之临其前，然后循其同异之辞，以度其屡迁之所由始而极其终，则虽千变万化，终冇典常，其条理粲然，不可紊也。故曰：「苟非其人，道不虚行。」记曰：「甘受和，白受采，小人不知天命而不畏也。」则其侮圣人之言宜矣。而望道之行，知是书之不可远，不亦难乎？或曰：此章既言「不可为典要」，又曰「既有典常」，何也？曰：德无常师，主善为师，则善者其常也。善无常主，协于克一，则一者其常也。是故上下旡常，刚柔相易，则不可为典要矣。同归而殊涂，百虑而一致，是岂不可为典常哉？今之言易者，或睹其形似而妄一其义，及其不可通，则又妄二其说。从而诘之，则曰「易不可为典要」者也。岂不缪哉？易之为书也，原始要终，以为质也。六爻相杂，唯其时物也。其初难知，其上易知，本末也。初辞拟之，卒成之终。若夫杂物撰德，辨是与非，则非其中爻不备。噫！亦要存亡吉凶，则居可知矣。知者观其彖辞，则思过半矣。二与四同功而异位，其善不同，二多誉，四多惧，近也。柔之为道，不利远者，其要无咎，其用柔中也。三与五同功而异位，三多凶，五多功，贵贱之等也。其柔危，其刚胜邪？前章既言易有典常，此章遂论其统要之所在。说文曰：「质，主也。」原其始于初，要其终于上，以为一卦之主也。虽六爻相杂，疑若难明，唯其物之当乎时，斯为主矣。其初难知，其上易知者，本藏而末见，积累之微，而成效之著，依违之未定，而向背之已明也。故爻之辞，初而拟之，卒而成之。「拟之」者，言其未定也。「成之」者，言其已然也。「终」字亦衍文。卒之为言终也，与前章衍「开」字同。若夫杂以阴阳之物、刚柔之撰、仁义之德，而辨其是非，则非其中爻不备。何者？本末虽在于初上，而是非决于中爻也。中爻者，二三四五是也。二三四五俱谓中爻，何也？曰：由三画而言之，则二五为中；由六画而言之，而三四为中；由初上而言之，则二三四五俱为中也。求本末于初上，辨是非于中爻，夫岂易哉？故夫子从而噫之，以为学者苟求之而弗得，亦不过要其如是而存，如是而亡，如是而吉，如是而凶，则居然可知矣。存亡吉凶，爻则有之，而彖辞固已指其所在，是以智者观之，思过半矣。二与四，三与五，刚柔同而上下异之，以其善不同。「二多誉，四多惧」，何也？二远而四近也。柔而近尊，进退危疑，是以多惧也。远既无咎，柔又得中，是以多誉也。「三多凶，五多功」，何也？五贵而三贱也。三五皆柔，则三危而五不危，是以多凶也。三、五皆刚，则五胜而三不胜，是以多功也。学者以此辨其中爻，而原始要终，以为其质，考其时物，观其彖辞，将无余蕴矣，乌在其不可为典要也哉？一云：柔之为道，有利不利，文脱二字。亦或然矣。易之为书也，广大悉备，有天道焉，有人道焉，有地道焉。兼三才而两之，故六。六者非它也，三才之道也。道有变动，故曰爻。爻有等，故曰物。物相杂，故曰文。文不当，故吉凶生焉。前章既言六爻之辨，此章遂论其本诸三才而悉备，故曰：「夫易广矣，大矣，备矣。」说卦曰：「立天之道，曰阴与阳；立地之道，曰柔与刚；立人之道，曰仁与义。」是谓兼三才而两之，故曰：六爻之动，三极之道也。道有变动，故曰爻。爻者，效也。爻有等衰，故曰物。物者，象也。物相杂，故曰文。文者，经纬也。位以为经，爻以为纬，错而成文。文有当不当，故吉凶生焉。当不当云者，爻位相得不相得故也。故曰吉凶者，言乎其失得也。凡此之义，二篇之中反复言之，不一二见而已。考其辞旨重复，不类他经之简严，故近世儒者或疑二篇之文非夫子之作，不知夫子所以赞易为传而不为经，其体固如此也。为是说者，读易而不知其义者也。苟知其义，则无是言矣。子贡曰：「君子一言以为智，一言以为不智，言不可不慎也。」信哉！易之兴也，其当殷之末世，周之盛德邪？当文王与纣之事邪？是故其辞危。危者使平，易者使倾，其道甚大，百物不废，惧以终始，其要无咎，此之谓易之道也。前三章言易之为书备矣，此章遂申明是书作于文王，而成于周公。夫周公既已作礼乐以维持当世，措之于太和之域，而是书盖衰世忧患之意，辞旨渊奥，非中材小智所可窥测，故存其书而不著其人，将有待于后圣，而世或未之知也欤？夫子是以三叹而言之也。然则夫子何以知之？以其辞危而知之也。夫殷之未亡，贤圣之君六七作。周自后稷、公刘积德累仁，至乎古公季历，肇基王业，而传之文王。纣为天子，令行禁止，脯醢诸侯，莫敢不听。文王三分天下有其二，而北面为臣，脱于囚虏。当此之时，可谓危矣。文王身当其事，而周公目睹其时，夫安得不危？文王危之，故虽险而卒平；纣唯易之，故虽强而卒倾。其在易，「蹇」而受之以解，危者使平也；「丰」而受之以旅，易者使倾也，皆文王与纣之事也。其余卦爻，亦莫不然。兹因消息盈虚之理，求其为之者而不得，以为易实使之也。夫极于大者，小或有所遗；精于小者，大或有所局。唯易之为书，广大悉备，是以其道甚大，而百物不废也。然苟能戒惧以终始者，其要归于无咎，此则易之道也。是故君子有终身之忧，而无一朝之患。其于是书，虽曰未学，吾必谓之学矣。夫乾，天下之至健也，德行恒易以知险。夫坤，天下之至顺也，德行恒简以知阻。能说诸心，能研诸侯之虑，定天下之吉凶，成天下之亹亹者。是故变化云为，吉事有祥，象事知器，占事知来。天地设位，圣人成能。人谋鬼谋，百姓与能。八卦以象告，爻彖以情言。刚柔杂居，而吉凶可见矣。变动以利言，吉凶以情迁。是故爱恶相攻而吉凶生，远近相取而悔吝生，情伪相感而利害生。凡易之情，近而不相得则凶，或害之，悔且吝。将叛者其辞惭，中心疑者其辞枝。吉人之辞寡，躁人之辞多，诬善之人其辞游，失其守者其辞屈。前章既言易之辞危，而知惧者可以无咎，此章遂申言易本于乾坤，以乾坤而成爻象，以易简而知险阻，至于爱恶情伪，枝游惭屈，无所遁其情，是故其辞不得不危也。夫爻象虽皆出于乾坤，然八卦既成列矣，则六子之德行不得不与乾坤异。乾之健确然，故恒易。坤之顺𬯎然，故恒简。震坎艮，刚而杂乎柔，故多险。巽离兑，柔而杂乎刚，故多阻。以乾坤之易简，知爻象之险阻，则能说诸心，诸研诸虑。以此定天下之吉凶，则无不定；以此成天下之事业，则无不成。「亹亹」，勉也，事业之所成也。「侯之」二字衍文，苏氏已得之。之王弼例引用此文，亦无「侯之」二字，韩康伯以来衍之矣。云者，言也。为者，动也。言动象占，所谓「圣人之道四焉」者也。「变化云为」，则所谓「拟议以成变化」是也。「吉事有祥」，则言动之几，吉之先见是也。「象事知器」，则「备物致用」，「立成器以为天下利」是也。占事知来，则所谓「无有远近幽深，遂知来物」是也。兼斯四者，圣人所以与天地参者乎？故曰「天地设位，圣人成能」。至于明则谋之人，幽则谋之鬼，虽百姓之愚，亦可使与能之矣。犹中庸所谓「夫妇之愚可以与知焉，夫妇之不肖可以能行焉」。盖圣人与民同患，而所以开觉延纳之者如此。百姓与能，故谋乎人鬼，圣人成能，故赞乎天地也。一卦之象可复八卦，是谓以象告；屯、蒙、需、讼，初九、六二，是谓以情言。变而通之以尽利，是谓以利言。吉凶悔吝生乎动，是谓以情迁。远近者言其地，爱恶者言其情，情伪者言其德，或相得或不相得，或有害或无害，斯吉凶悔吝之所从生也。其义则爻象之辞备之矣。叛者恧其心，故其辞惭；疑者惑其志，故其辞枝；诬善之人难于指实，故其辞游；失其守者难以求信，故其辞屈。诸如此类，作易者各准其情而为之辞，盖不止于是。学者详论而深思焉，则得之矣。临川王氏曰：六者之辞，于易无有，其或然欤！周易经传集解卷三十四。",-1)])])}const _=t(r,[["render",c]]);export{m as __pageData,_ as default};
